import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"smql codegen","description":"","frontmatter":{},"headers":[],"relativePath":"cli/codegen.md","filePath":"cli/codegen.md"}'),d={name:"cli/codegen.md"};function o(n,e,c,l,p,r){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="smql-codegen" tabindex="-1">smql codegen <a class="header-anchor" href="#smql-codegen" aria-label="Permalink to &quot;smql codegen&quot;">​</a></h1><p>Generate typed Rust code from <code>.smql</code> machine definitions. Produces one <code>.rs</code> file per machine plus a <code>mod.rs</code> with <code>pub mod</code> declarations.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [OPTIONS]</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Short</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--input</code></td><td><code>-i</code></td><td><em>(required)</em></td><td>Input <code>.smql</code> files or directories (can be specified multiple times)</td></tr><tr><td><code>--output</code></td><td><code>-o</code></td><td><code>src/generated</code></td><td>Output directory for generated Rust files</td></tr><tr><td><code>--lang</code></td><td><code>-l</code></td><td><code>rust</code></td><td>Target language (only <code>&quot;rust&quot;</code> is currently supported)</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Generate code from all <code>.smql</code> files in a directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/generated</span></span></code></pre></div><p>Specify multiple input files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines/order.smql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines/ticket.smql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/gen</span></span></code></pre></div><p>Use the default output directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">smql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines/</span></span></code></pre></div><h2 id="generated-output" tabindex="-1">Generated Output <a class="header-anchor" href="#generated-output" aria-label="Permalink to &quot;Generated Output&quot;">​</a></h2><p>For each machine definition found in the input files, <code>smql codegen</code> produces a Rust module containing typed representations of the machine&#39;s states, data fields, and transitions.</p><p>Given a machine named <code>SupportTicket</code>, the codegen produces:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/generated/</span></span>
<span class="line"><span>  mod.rs              # pub mod declarations</span></span>
<span class="line"><span>  support_ticket.rs   # typed code for SupportTicket</span></span></code></pre></div><h3 id="type-mapping" tabindex="-1">Type Mapping <a class="header-anchor" href="#type-mapping" aria-label="Permalink to &quot;Type Mapping&quot;">​</a></h3><p>SMQL data types map to Rust types as follows:</p><table tabindex="0"><thead><tr><th>SMQL Type</th><th>Rust Type</th></tr></thead><tbody><tr><td><code>TEXT</code></td><td><code>String</code></td></tr><tr><td><code>INT</code></td><td><code>i64</code></td></tr><tr><td><code>FLOAT</code></td><td><code>f64</code></td></tr><tr><td><code>BOOL</code></td><td><code>bool</code></td></tr><tr><td><code>MONEY</code></td><td><code>(i64, String)</code></td></tr><tr><td><code>REF</code></td><td><code>String</code></td></tr><tr><td><code>LIST</code></td><td><code>Vec&lt;serde_json::Value&gt;</code></td></tr><tr><td><code>MAP</code></td><td><code>std::collections::BTreeMap&lt;String, serde_json::Value&gt;</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The <code>--input</code> flag can point to individual <code>.smql</code> files or directories. When given a directory, all <code>.smql</code> files in that directory are processed.</li><li>Machine names are converted to <code>snake_case</code> for file names and <code>PascalCase</code> for Rust type names.</li><li>Only the <code>&quot;rust&quot;</code> language target is supported at this time.</li></ul>`,22)])])}const g=t(d,[["render",o]]);export{u as __pageData,g as default};
